/**
 *
 * An interface representing AppInfo.
 * Describes an app.
 *
 */
type AppInfo = {
    /**
     * @member {string} [id] Unique identifier representing an app
     */
    id?: string;
    /**
     * @member {string} [version] Version of the app
     */
    version?: string;
};

export type { AppInfo };
